package com.treadz.console.programs.model

/**
 * Training program model: one immutable model for the three kinds of program.
 *
 *  - [ProgramKind.Standard]: shipped in the app's code as a relative template (percentages of an intensity range that
 *    the user picks when starting).
 *  - [ProgramKind.Free]: written by the user, absolute values by default.
 *  - [ProgramKind.Personalised]: generated by the app from the user's data and stored already generated, together with
 *    the generator metadata ([ProgramOrigin]).
 *
 * A program is never executed directly: it is first resolved into a concrete plan (see
 * `com.treadz.console.programs.plan.ProgramResolver`). The model classes do not check themselves on construction so
 * that an editor can hold a half-written program; use [ProgramValidator] before storing or resolving one.
 */
data class Program(
    /** Stable identifier: UUID text, or a `standard-...` slug for the standard programs shipped in the app. */
    val id: String,
    val name: String,
    val kind: ProgramKind,
    val steps: List<ProgramStep>,
    val description: String? = null,
    /** Only for [ProgramKind.Personalised]: what generated the program. */
    val origin: ProgramOrigin? = null,
    /** Version of the document format this program was written with. */
    val schemaVersion: Int = SCHEMA_VERSION,
) {
    /** Number of blocks once every [Repeat] is expanded. */
    val expandedBlockCount: Int
        get() = steps.sumOf { step ->
            when (step) {
                is Block -> 1
                is Repeat -> step.count.toLong() * step.blocks.size
            }
        }.coerceAtMost(Int.MAX_VALUE.toLong()).toInt()

    companion object {
        /** Current version of the JSON document format. */
        const val SCHEMA_VERSION = 1
    }
}

enum class ProgramKind { Standard, Free, Personalised }

/**
 * What produced a personalised program: the generator, its version and the inputs it used (profile, history…), as plain
 * text so the stored program can be explained and regenerated later.
 */
data class ProgramOrigin(
    val generatorId: String,
    val generatorVersion: Int,
    val inputs: Map<String, String> = emptyMap(),
)

/** A step of a program: a single [Block] or a [Repeat] of several blocks. Only one level of nesting exists. */
sealed interface ProgramStep

/** What the block is for. Used by the UI and for analysis; the engine treats all phases alike. */
enum class BlockPhase { WarmUp, Work, Recovery, CoolDown, Other }

/** One segment of the workout: it ends by time or by distance and has one [target]. */
data class Block(
    val phase: BlockPhase,
    val end: BlockEnd,
    val target: BlockTarget,
    /** Optional label ("4 min hard"). */
    val name: String? = null,
) : ProgramStep

/** [blocks] performed [count] times in a row. */
data class Repeat(val count: Int, val blocks: List<Block>) : ProgramStep

/** How a block ends. The treadmill's own time/distance countdowns are never used: the app keeps the clock. */
sealed interface BlockEnd {
    data class Duration(val seconds: Int) : BlockEnd
    data class Distance(val meters: Int) : BlockEnd
}

/** What a block asks of the treadmill. */
sealed interface BlockTarget {

    /** Fixed speed and incline, known when the program is written. */
    sealed interface Fixed : BlockTarget

    /** Speed in km/h and incline in %. */
    data class Absolute(val speedKmh: Double, val inclinePercent: Double) : Fixed

    /**
     * Speed and incline as a percentage (0-100) of the ranges chosen when the program starts: speed 0 % is the easy
     * speed and 100 % the maximum speed; incline 0 % is flat and 100 % the maximum incline.
     */
    data class Relative(val speedPercent: Double, val inclinePercent: Double) : Fixed

    /**
     * Keep the heart rate inside [zone] by adjusting [adjust] between [minimum] and [maximum], starting from [start].
     * The bounds are in the same scale as [start] (km/h or % for an absolute start; % of the range for a relative one)
     * and apply to the adjusted quantity. Heart-rate control is not available yet: such a block runs at its starting
     * values and the resolved plan says so.
     */
    data class HeartRate(
        val zone: HeartRateZone,
        val adjust: HeartRateAdjust,
        val minimum: Double,
        val maximum: Double,
        val start: Fixed,
    ) : BlockTarget
}

/** Target zone, as a percentage of [basis]. */
data class HeartRateZone(val basis: HeartRateBasis, val lowPercent: Int, val highPercent: Int)

enum class HeartRateBasis { MaxHeartRate, HeartRateReserve }

/** Which quantity the heart-rate control moves. */
enum class HeartRateAdjust { Speed, Incline }
